let productPhotos=[];
let state,local=false,busy=false,pendingAction;const $=s=>document.querySelector(s);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=v=>v===null?'Sob consulta':new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(v/100);
async function api(path,options={}){let r;try{r=await fetch(path,{...options,cache:'no-store',signal:AbortSignal.timeout(15000),headers:{'X-SOS-Admin':'1',...(options.body instanceof FormData?{}:{'Content-Type':'application/json'}),...options.headers}})}catch{throw Error('Não foi possível conectar ao painel. Tente novamente. Se estava salvando, confira os dados antes de repetir a operação.')}let data;try{data=await r.json()}catch{throw Error(r.status===404?'Este endereço abriu uma prévia sem o banco de dados. Use o endereço atual do painel.':'A resposta do servidor não pôde ser lida. Tente novamente.')}if(!r.ok)throw Error(data.error||'Não foi possível concluir a operação.');return data}
function message(text,error=false){$('#admin-message').textContent=text;$('#admin-message').classList.toggle('error',error)}
function lock(value){busy=value;document.querySelectorAll('button[type="submit"],form button:not([type]),#new-product,#new-service').forEach(b=>b.disabled=value)}
async function save(next){if(busy)throw Error('Aguarde a operação em andamento.');lock(true);try{state=await api('/api/admin/store',{method:'PUT',body:JSON.stringify(next)});render();message('Alterações salvas. A loja exibirá os novos dados ao abrir ou atualizar a página.')}finally{lock(false)}}
function formValue(form,name){return form.elements.namedItem(name)}
function render(){renderProducts();renderBanners();$('#save-status').textContent=state.updatedAt?'Última alteração: '+new Date(state.updatedAt).toLocaleString('pt-BR'):'Catálogo inicial — nenhuma alteração salva';$('#category-list').innerHTML=state.categories.map((c,i)=>`<article class="admin-row"><div class="details"><h3>${esc(c)}</h3><p>${state.products.filter(p=>p.category===c).length} produto(s)</p></div><div class="row-actions"><button data-category-rename="${i}">Renomear</button><button class="danger" data-category-delete="${i}">Excluir</button></div></article>`).join('');$('#admin-services').innerHTML=state.services.map((s,i)=>`<article class="admin-row"><div class="details"><h3>${esc(s.name)}</h3><p>${esc(s.description)}</p></div><div class="row-actions"><button data-service-edit="${i}">Editar</button><button class="danger" data-service-delete="${i}">Excluir</button></div></article>`).join('')||'<p class="empty">Nenhum serviço cadastrado.</p>'}
function renderProducts(){const q=$('#admin-search').value.toLocaleLowerCase('pt-BR');const list=state.products.filter(p=>`${p.name} ${p.category}`.toLocaleLowerCase('pt-BR').includes(q));$('#admin-products').innerHTML=list.map(p=>`<article class="admin-row">${p.image?`<img src="${esc(p.image)}" alt="">`:''}<div class="details"><h3>${esc(p.name)}</h3><p>${esc(p.category)} · ${money(p.price)} · ${p.mode==='cart'?'Carrinho':'WhatsApp'}</p><p><span class="visibility ${p.active===false?'off':''}">${p.active===false?'Oculto':'Visível'}</span></p></div><div class="row-actions"><button data-edit="${esc(p.id)}">Editar</button><button data-toggle="${esc(p.id)}">${p.active===false?'Exibir':'Ocultar'}</button><button class="danger" data-delete="${esc(p.id)}">Excluir</button></div></article>`).join('')||'<p class="empty">Nenhum produto encontrado. Cadastre um produto ou altere a busca.</p>'}
function editProduct(id){const p=state.products.find(p=>p.id===id)||{id:'',name:'',category:state.categories[0],price:null,mode:'whatsapp',description:'',image:'',icon:'cpu',active:true};const f=$('#product-form');f.reset();f.querySelector('.editor-error').textContent='';formValue(f,'category').innerHTML=state.categories.map(c=>`<option>${esc(c)}</option>`).join('');productPhotos=[...(Array.isArray(p.images)?p.images:(p.image?[p.image]:[]))];renderPhotoEditor();for(const key of ['id','name','category','mode','description','icon'])formValue(f,key).value=p[key]||'';formValue(f,'price').value=p.price===null?'':(p.price/100).toFixed(2);formValue(f,'active').checked=p.active!==false;$('#product-editor-title').textContent=id?'Editar produto':'Cadastrar produto';$('#product-editor').showModal()}
function editService(index){const f=$('#service-form');f.reset();f.querySelector('.editor-error').textContent='';const s=state.services[index]||{name:'',description:'',icon:'wrench'};formValue(f,'index').value=index??'';for(const key of ['name','description','icon'])formValue(f,key).value=s[key];$('#service-editor').showModal()}
function confirmAction(text,fn,rename){pendingAction=fn;$('#confirm-description').textContent=text;$('#rename-label').classList.toggle('hidden',rename===undefined);formValue($('#confirm-form'),'newName').value=rename||'';formValue($('#confirm-form'),'newName').required=rename!==undefined;$('#confirm-form .editor-error').textContent='';$('#confirm-editor').showModal()}
function fillSettings(){const f=$('#settings-form');for(const key of ['name','phone','color','headline','highlight','description','address','hours'])formValue(f,key).value=state.settings[key]||'';formValue(f,'demo').checked=state.settings.demo;$('#brand-fields').innerHTML=[['logo','Logo da loja'],['favicon','Ícone da aba (favicon)']].map(([key,label])=>`<label>${label}<img class="upload-preview" src="${esc(state.settings[key])}" alt="${label}"><input name="${key}" value="${esc(state.settings[key])}" placeholder="Endereço HTTPS da imagem"><input type="file" accept="image/png,image/jpeg,image/webp" data-upload="${key}"><small>PNG, JPEG ou WebP, até 3 MB.</small></label>`).join('')}
async function init(){message('' ); const retryButton=document.querySelector('#retry-access'); if(retryButton)retryButton.hidden=true; try{const session=await api('/api/session');local=session.local;if(session.provider==='cloudflare'){$('#signin').href=session.loginUrl;$('#signin').textContent='Entrar no painel';window.sosLogoutUrl=session.logoutUrl}if(!session.authenticated){$('#auth-description').textContent=local?'Esta prévia só aceita administração neste computador. Os dados ficam salvos localmente até a publicação.':'Entre com a conta proprietária da loja para gerenciar o conteúdo.';$(local?'#local-signin':'#signin').classList.remove('hidden');return}state=await api('/api/admin/store');$('#auth-panel').classList.add('hidden');$('#admin-workspace').classList.remove('hidden');$('#local-notice').classList.toggle('hidden',!local);render();fillSettings()}catch(e){$('#auth-description').textContent=e.message;message(e.message,true); document.querySelector('#retry-access').hidden=false}}
$('#local-signin').onclick=async()=>{try{await api('/api/local-login',{method:'POST',body:'{}'});await init()}catch(e){message(e.message,true)}};
$('#signout').onclick=async()=>{if(local){await api('/api/local-logout',{method:'POST',body:'{}'});location.reload()}else location.href=window.sosLogoutUrl||'/signout-with-chatgpt?return_to=%2Fadmin.html'};
$('#admin-search').addEventListener('input',renderProducts);$('#new-product').onclick=()=>editProduct();$('#new-service').onclick=()=>editService();
document.addEventListener('click',async event=>{const b=event.target.closest('button');if(!b||busy)return;try{if(b.dataset.panel){document.querySelectorAll('[id^="panel-"]').forEach(p=>p.classList.toggle('hidden',p.id!=='panel-'+b.dataset.panel));document.querySelectorAll('[data-panel]').forEach(t=>{t.classList.toggle('active',t===b);t.setAttribute('aria-pressed',String(t===b))})}if(b.dataset.dismiss)document.getElementById(b.dataset.dismiss).close();if(b.dataset.edit)editProduct(b.dataset.edit);if(b.dataset.toggle){const next=structuredClone(state);const p=next.products.find(p=>p.id===b.dataset.toggle);p.active=p.active===false;await save(next)}if(b.dataset.delete)confirmAction('Excluir este produto do catálogo? Esta ação remove seu cadastro.',async()=>{const next=structuredClone(state);next.products=next.products.filter(p=>p.id!==b.dataset.delete);await save(next)});if(b.dataset.serviceEdit!==undefined)editService(Number(b.dataset.serviceEdit));if(b.dataset.serviceDelete!==undefined)confirmAction('Excluir este serviço da página inicial?',async()=>{const next=structuredClone(state);next.services.splice(Number(b.dataset.serviceDelete),1);await save(next)});if(b.dataset.categoryRename!==undefined){const old=state.categories[Number(b.dataset.categoryRename)];confirmAction('Informe o novo nome da categoria.',async name=>{const next=structuredClone(state);next.categories[next.categories.indexOf(old)]=name;next.products.forEach(p=>{if(p.category===old)p.category=name});await save(next)},old)}if(b.dataset.categoryDelete!==undefined){const category=state.categories[Number(b.dataset.categoryDelete)];if(state.products.some(p=>p.category===category))throw Error('Mova os produtos desta categoria antes de excluí-la.');confirmAction(`Excluir a categoria “${category}”?`,async()=>{const next=structuredClone(state);next.categories=next.categories.filter(c=>c!==category);await save(next)})}}catch(e){message(e.message,true)}});
$('#product-form').onsubmit=async event=>{event.preventDefault();const f=event.target;try{const d=Object.fromEntries(new FormData(f));const parseLines=(text,mapper)=>String(text||'').split('\n').map(s=>s.trim()).filter(Boolean).map(mapper);const specs=parseLines(d.specsText,line=>{const i=line.indexOf(':');return{label:i<0?line:line.slice(0,i).trim(),value:i<0?'':line.slice(i+1).trim()}});const reviews=parseLines(d.reviewsText,line=>{const parts=line.split('|').map(s=>s.trim());return{name:parts[0]||'Cliente',rating:Math.min(5,Math.max(1,Number(parts[1])||5)),text:parts.slice(2).join(' | '),image:'',verified:false}});const next=structuredClone(state);const description=(d.longDescription||d.description||'').trim();const p={id:d.id||crypto.randomUUID(),name:d.name,category:d.category,description,longDescription:description,descriptionBlocks:readDescriptionBlocks(),brand:d.brand,model:d.model,sku:d.sku,paymentInfo:d.paymentInfo,specs,reviews,detailImages:[...(window.__sosDetailPhotos||[])],mode:d.mode,icon:d.icon,image:productPhotos[0]||'',images:[...productPhotos],active:formValue(f,'active').checked,price:d.price===''?null:Math.round(Number(d.price)*100)};const i=next.products.findIndex(p=>p.id===d.id);if(i<0)next.products.push(p);else next.products[i]=p;await save(next);$('#product-editor').close()}catch(e){f.querySelector('.editor-error').textContent=e.message}};
$('#service-form').onsubmit=async event=>{event.preventDefault();const f=event.target;try{const d=Object.fromEntries(new FormData(f));const next=structuredClone(state);const s={name:d.name,description:d.description,icon:d.icon};if(d.index==='')next.services.push(s);else next.services[Number(d.index)]=s;await save(next);$('#service-editor').close()}catch(e){f.querySelector('.editor-error').textContent=e.message}};
$('#category-form').onsubmit=async event=>{event.preventDefault();try{const next=structuredClone(state);next.categories.push(formValue(event.target,'name').value.trim());await save(next);event.target.reset()}catch(e){message(e.message,true)}};
$('#settings-form').onsubmit=async event=>{event.preventDefault();try{const f=event.target;const next=structuredClone(state);next.settings={...next.settings,...Object.fromEntries(new FormData(f)),demo:formValue(f,'demo').checked};await save(next);fillSettings()}catch(e){message(e.message,true)}};
$('#confirm-form').onsubmit=async event=>{event.preventDefault();try{await pendingAction(formValue(event.target,'newName').value.trim());$('#confirm-editor').close()}catch(e){event.target.querySelector('.editor-error').textContent=e.message}};
document.addEventListener('change',async event=>{const input=event.target;if(!input.dataset.upload||!input.files[0])return;const file=input.files[0];const form=input.closest('form');const error=form.querySelector('.editor-error');try{if(file.size>3145728)throw Error('Selecione uma imagem de até 3 MB.');const data=new FormData();data.append('image',file);input.disabled=true;lock(true);const result=await api('/api/admin/upload',{method:'POST',body:data});formValue(form,input.dataset.upload).value=result.url;const img=input.closest('label').querySelector('img');if(img){img.src=result.url;img.hidden=false}if(error)error.textContent='Imagem enviada. Salve o formulário para aplicá-la.';else message('Imagem enviada. Salve as configurações para aplicá-la.')}catch(e){if(error)error.textContent=e.message;else message(e.message,true)}finally{input.disabled=false;input.value='';lock(false)}});
// Upload paths are same-origin, so the field accepts both paths and HTTPS URLs.
$('#product-form [name="image"]').type='text';
const detailFields=document.createElement('div');detailFields.className='form-grid product-detail-fields';detailFields.innerHTML='<label>Marca<input name="brand" maxlength="100" placeholder="Ex.: ASUS"></label><label>Modelo<input name="model" maxlength="100" placeholder="Ex.: X515"></label><label>SKU<input name="sku" maxlength="80" placeholder="Código do produto"></label><label class="span-two">Descrição completa<textarea name="longDescription" maxlength="5000" rows="5" placeholder="Conte todos os detalhes do produto."></textarea></label><label class="span-two">Informações de pagamento<textarea name="paymentInfo" maxlength="600" rows="3" placeholder="Ex.: pagamento pelo site em preparação; confirme disponibilidade pelo WhatsApp."></textarea></label><label class="span-two">Ficha técnica, uma linha por item<textarea name="specsText" maxlength="8000" rows="5" placeholder="Tela: 15,6 polegadas\nMemória: 8 GB\nArmazenamento: 480 GB"></textarea></label><label class="span-two">Avaliações de compradores, uma por linha no formato Nome | Nota | Comentário<textarea name="reviewsText" maxlength="20000" rows="5" placeholder="Nome do cliente | 5 | Comentário sobre o produto"></textarea></label>';$('#product-form .form-grid').prepend(detailFields);
function fillProductDetailFields(p){const f=$('#product-form');for(const key of ['brand','model','sku','longDescription','paymentInfo'])formValue(f,key).value=p[key]||'';formValue(f,'specsText').value=(p.specs||[]).map(s=>`${s.label}: ${s.value}`).join('\n');formValue(f,'reviewsText').value=(p.reviews||[]).map(r=>`${r.name} | ${r.rating} | ${r.text}`).join('\n')}
const originalEditProduct=editProduct;editProduct=function(id){originalEditProduct(id);const p=state.products.find(p=>p.id===id)||{};fillProductDetailFields(p)};
const detailScript=document.createElement('script');detailScript.src='admin-details.js';document.head.append(detailScript);const retryAccess=document.createElement('button');retryAccess.id='retry-access';retryAccess.className='button outline';retryAccess.textContent='Tentar novamente';retryAccess.hidden=true;retryAccess.onclick=init;$('#auth-panel').append(retryAccess);
if(location.hostname==='127.0.0.1'&&['4173','4174'].includes(location.port)){location.replace('http://127.0.0.1:4175/admin.html')}else{init()}



function renderPhotoEditor(){$('#gallery-preview').innerHTML=productPhotos.map((url,i)=>'<div class="gallery-thumb"><img src="'+esc(url)+'" alt="Foto '+(i+1)+'"><span>'+(i===0?'Capa':'Foto '+(i+1))+'</span><div><button type="button" data-photo-cover="'+i+'" '+(i===0?'disabled':'')+'>Usar como capa</button><button type="button" data-photo-remove="'+i+'">Remover</button></div></div>').join('')}
$('#add-photo-url').onclick=()=>{const field=formValue($('#product-form'),'image');const value=field.value.trim();const error=$('#product-form .editor-error');if(!/^https:\/\//.test(value)){error.textContent='Informe um endereço HTTPS válido.';return}if(productPhotos.length>=10){error.textContent='Limite de 10 fotos por produto.';return}productPhotos.push(value);field.value='';error.textContent='';renderPhotoEditor()};
document.addEventListener('click',e=>{if(busy)return;const b=e.target.closest('[data-photo-remove],[data-photo-cover]');if(!b)return;if(b.dataset.photoRemove!==undefined)productPhotos.splice(Number(b.dataset.photoRemove),1);else productPhotos.unshift(productPhotos.splice(Number(b.dataset.photoCover),1)[0]);renderPhotoEditor()});
$('#gallery-upload').addEventListener('change',async e=>{const files=[...e.target.files];const error=$('#product-form .editor-error');if(files.length+productPhotos.length>10){error.textContent='Use até 10 fotos por produto.';e.target.value='';return}if(files.some(f=>f.size>3145728)){error.textContent='Cada foto deve ter no máximo 3 MB.';e.target.value='';return}lock(true);e.target.disabled=true;try{for(let i=0;i<files.length;i++){error.textContent='Enviando foto '+(i+1)+' de '+files.length+'…';const data=new FormData();data.append('image',files[i]);const result=await api('/api/admin/upload',{method:'POST',body:data});productPhotos.push(result.url);renderPhotoEditor()}error.textContent='Fotos enviadas. Clique em Salvar produto para aplicá-las.'}catch(err){error.textContent=err.message+' As fotos já enviadas continuam no formulário.'}finally{e.target.value='';e.target.disabled=false;lock(false)}});
(()=>{const key='sos-theme';const saved=localStorage.getItem(key);if(saved==='dark'||saved==='light')document.documentElement.dataset.theme=saved;const header=document.querySelector('.header-inner');if(!header||header.querySelector('.theme-toggle'))return;const button=document.createElement('button');button.type='button';button.className='theme-toggle';button.setAttribute('aria-label','Ativar modo noturno');button.innerHTML='<span aria-hidden="true">☾</span><span class="theme-toggle-label">Modo noturno</span>';const update=()=>{const dark=document.documentElement.dataset.theme==='dark';button.setAttribute('aria-label',dark?'Ativar modo claro':'Ativar modo noturno');button.innerHTML=dark?'<span aria-hidden="true">☀</span><span class="theme-toggle-label">Modo claro</span>':'<span aria-hidden="true">☾</span><span class="theme-toggle-label">Modo noturno</span>'};button.onclick=()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;localStorage.setItem(key,next);update()};header.append(button);update()})();
